{"output":"1\t#!/usr/bin/env bash\n2\t# collect_mysql.sh - 采集 MySQL 8.4 LTS tar.xz（硬性要求 8.4.x）\n3\t# 架构支持：x86_64（glibc2.17 + glibc2.28 双变体）/ aarch64（仅 glibc2.28 官方构建）\n4\t# loongarch64 已移除支持\n5\t\n6\tset -Eeuo pipefail\n7\tSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\n8\tsource \"${SCRIPT_DIR}/lib.sh\"\n9\t\n10\tFAMILY=\"${TARGET_FAMILY:-$(auto_detect_family)}\"\n11\tARCH_VAL=\"${TARGET_ARCH:-$(auto_detect_arch)}\"\n12\t\n13\t# 架构白名单\n14\tcase \"${ARCH_VAL}\" in\n15\t    x86_64|aarch64) : ;;\n16\t    *) die \"${EX_USAGE}\" \"仅支持 x86_64 / aarch64，当前架构：${ARCH_VAL}\" ;;\n17\tesac\n18\t\n19\tOUT_DIR=\"${PKG_DIR}/${FAMILY}/${ARCH_VAL}/mysql\"\n20\tmkdir -p \"${OUT_DIR}\"\n21\t\n22\t# 版本硬性要求：MySQL 8.4.x（可用环境变量 MYSQL_VERSION 覆盖小版本，仍必须在 8.4 系列内）\n23\tMYSQL_VERSION=\"${MYSQL_VERSION:-8.4.6}\"\n24\tcase \"${MYSQL_VERSION}\" in\n25\t    8.4.*) : ;;\n26\t    *) die \"${EX_USAGE}\" \"MySQL 版本硬性要求 8.4.x，当前配置：${MYSQL_VERSION}\" ;;\n27\tesac\n28\t\n29\t# 双重校验：文件名 + tarball 顶层目录都必须是 mysql-8.4.*\n30\tcheck_mysql_tarball() {\n31\t    local f=\"$1\"\n32\t    local base; base=\"$(basename \"${f}\")\"\n33\t    case \"${base}\" in\n34\t        mysql-8.4.*) : ;;\n35\t        *) err \"MySQL 硬性要求 8.4.x，拒绝收录：${base}\"; return 1 ;;\n36\t    esac\n37\t    # 全量完整性校验：xz -t 会解压校验整个流，残卷/断点续传未完成的包必失败\n38\t    if ! xz -t \"${f}\" 2>/dev/null; then\n39\t        err \"tarball 不完整（xz 校验失败，可能是断点续传残卷）：${base}\"\n40\t        return 1\n41\t    fi\n42\t    local top\n43\t    top=\"$(tar -tf \"${f}\" 2>/dev/null | head -n1 || true)\"\n44\t    case \"${top}\" in\n45\t        mysql-8.4.*) : ;;\n46\t        *) err \"tarball 内容与 8.4.x 不符（顶层目录：${top:-无法识别}），拒绝收录：${base}\"; return 1 ;;\n47\t    esac\n48\t    return 0\n49\t}\n50\t\n51\t# 本地优先（仍须满足 8.4.x，不符合则直接报错退出，不静默收录）\n52\tfor cand in \"${HOME}/mysql\"*.tar.xz /opt/mysql*.tar.xz /usr/local/mysql*.tar.xz; do\n53\t    if [[ -f \"${cand}\" ]]; then\n54\t        if check_mysql_tarball \"${cand}\"; then\n55\t            cp -n \"${cand}\" \"${OUT_DIR}/\"\n56\t            info \"已复制本地 MySQL: ${cand}\"\n57\t            exit 0\n58\t        else\n59\t            die \"${EX_USAGE}\" \"本地 MySQL 包不符合 8.4.x 硬性要求，请替换为 mysql-8.4.x tarball 后重试\"\n60\t        fi\n61\t    fi\n62\tdone\n63\t\n64\t# 下载指定 glibc 变体（直存 OUT_DIR，支持跨运行断点续传）\n65\tdownload_variant() {\n66\t    local tag=\"$1\"\n67\t    local fname=\"mysql-${MYSQL_VERSION}-linux-${tag}-${ARCH_VAL}.tar.xz\"\n68\t    local out_file=\"${OUT_DIR}/${fname}\"\n69\t    # 已存在且通过 tar 校验的完整包才跳过（残卷会续传补齐）\n70\t    if [[ -f \"${out_file}\" ]] && check_mysql_tarball \"${out_file}\"; then\n71\t        info \"已存在完整包，跳过下载：${fname}\"\n72\t        return 0\n73\t    fi\n74\t    local url=\"https://dev.mysql.com/get/Downloads/MySQL-8.4/${fname}\"\n75\t    info \"下载：${fname}（断点续传，最多 3 轮重试）\"\n76\t    local dl_ok=0\n77\t    local _try\n78\t    for _try in 1 2 3; do\n79\t        _ec=0\n80\t        curl -fsSL --retry 2 --retry-delay 3 -C - \"${url}\" -o \"${out_file}\" && _ec=0 || _ec=$?\n81\t        if [[ ${_ec} -eq 0 ]] && check_mysql_tarball \"${out_file}\"; then\n82\t            dl_ok=1\n83\t            break\n84\t        fi\n85\t        # 退出码 22 = HTTP 错误（如 404）：dev.mysql.com 只保留 8.4 系列较新的补丁版，\n86\t        # 旧补丁版会挪到 downloads.mysql.com/archives，重试必然还是 404，立即终止\n87\t        if [[ ${_ec} -eq 22 ]]; then\n88\t            warn \"${url} 返回 HTTP 错误（该地址无此版本，属永久性 404），跳过重试\"\n89\t            break\n90\t        fi\n91\t        warn \"下载中断（第 ${_try}/3 轮）：${fname}，断点续传重试中...\"\n92\t        sleep 3\n93\t    done\n94\t    if [[ \"${dl_ok}\" -eq 1 ]]; then\n95\t        ok \"已就绪：${out_file}\"\n96\t        return 0\n97\t    fi\n98\t    warn \"下载失败：${fname}（可人工放到 ${OUT_DIR}/ 后重跑）\"\n99\t    return 1\n100\t}\n101\t\n102\tcase \"${ARCH_VAL}\" in\n103\t    x86_64)\n104\t        # 官方同时发布 glibc2.17 / glibc2.28 构建，双变体都采：\n105\t        # 客户机 glibc 2.17（CentOS7/麒麟 V10 SP1 等）与 >=2.28（el8 系/openEuler 等）都能覆盖\n106\t        download_variant \"glibc2.17\" || true\n107\t        download_variant \"glibc2.28\" || true\n108\t        ;;\n109\t    aarch64)\n110\t        # 官方仅发布 glibc2.28 构建；aarch64 + glibc2.17 客户机（麒麟 V10 SP1 鲲鹏等）不支持，\n111\t        # install_mysql.sh 会在部署时明确拒绝\n112\t        download_variant \"glibc2.28\" || true\n113\t        ;;\n114\tesac\n115\t\n116\t# 校验最终产物：至少一个 8.4.x tarball\n117\tif ! ls \"${OUT_DIR}\"/mysql-8.4.*.tar.xz >/dev/null 2>&1; then\n118\t    die \"${EX_DEPS}\" \"未采集到任何 MySQL 8.4.x tarball，请检查网络或人工放置到 ${OUT_DIR}/\"\n119\tfi\n120\tok \"MySQL 采集完成：${OUT_DIR}/\"\n121\texit 0"}